import{c as t,Q as n,j as o,m as s}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"The event dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/dashboard.md","filePath":"user/running-the-event/dashboard.md"}'),a={name:"user/running-the-event/dashboard.md"};function r(i,e,h,d,l,g){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="the-event-dashboard" tabindex="-1">The event dashboard <a class="header-anchor" href="#the-event-dashboard" aria-label="Permalink to &quot;The event dashboard&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators watching and running the event on the day.</p><p>The dashboard is your home base while an event runs — open it on the operator&#39;s screen and leave it up. It&#39;s the landing page for an event and gives you, at a glance, the event&#39;s status, how many competitors are still out, the health of your radio network, and one-click access to the jobs you do most. This page explains every card and indicator, and what to do when one changes colour.</p><h2 id="the-top-bar-status-and-event-controls" tabindex="-1">The top bar: status and event controls <a class="header-anchor" href="#the-top-bar-status-and-event-controls" aria-label="Permalink to &quot;The top bar: status and event controls&quot;">​</a></h2><p>The strip across the top of every event page (not just the dashboard) carries the event&#39;s lifecycle:</p><ul><li><strong>Status chip</strong> — the event&#39;s current state: <ul><li><strong>Setup</strong> — not started yet (you&#39;re still preparing it)</li><li><strong>Live</strong> — running; the chip pulses</li><li><strong>Testing</strong> — running in test mode (see below)</li><li><strong>Stopping…</strong> — on its way to finished</li><li><strong>Interrupted</strong> — it was live when Manager was closed or the computer stopped, and hasn&#39;t been resumed</li><li><strong>Abandoned</strong> — an interrupted event you chose not to resume</li><li><strong>Complete</strong> — finished</li></ul></li><li><strong>Event clock</strong> — the running event time, shown while the event is live.</li><li><strong>Live standby chip</strong> — when a second computer is keeping a live copy of this event, a chip says whether it is up to date. See <a href="./live-standby">Live standby</a>.</li><li><strong>The primary button</strong> changes with the state: <strong>Start event</strong> (in setup), <strong>Finish event</strong> (while live), or <strong>Resume event</strong> (for an interrupted or abandoned event, alongside <strong>Mark finished</strong>). Once an event is complete there&#39;s nothing left to do, so <strong>Close</strong> becomes the primary button and <strong>Restart event</strong> sits alongside it as a quiet, secondary option. <strong>Close</strong> is always there and takes you back to the events list; it doesn&#39;t stop the event.</li><li><strong>Replay</strong> appears on an event that has captured data to replay, when no event is live; this is a testing/training tool rather than something you use on the day. While a replay runs, the replay controls sit in the bar and the finish button reads <strong>Stop replay</strong> (or <strong>Exit replay</strong> once it reaches the end).</li></ul><h3 id="starting-and-finishing" tabindex="-1">Starting and finishing <a class="header-anchor" href="#starting-and-finishing" aria-label="Permalink to &quot;Starting and finishing&quot;">​</a></h3><p><strong>Start event</strong> first runs Manager&#39;s pre-start checks. If they find anything — no courses, classes or competitors, classes with no course, or starts that go into the forest together — they&#39;re listed under <strong>Event validation warnings</strong>, and you can <strong>Continue</strong> anyway or go back and fix them. Another event already being live doesn&#39;t stop it: both run (see <a href="#two-events-live-at-once">Two events live at once</a>). The one thing that does is a replay, which has to be stopped first.</p><p>An event dated <strong>in the future</strong> asks <strong>Start event in test mode?</strong> before it starts. A test-mode event runs exactly like a live one — downloads, radio punches, screens — so you can rehearse the day; the chip reads <strong>Testing</strong> and the finish button <strong>Finish test</strong>.</p><p><strong>Finish event</strong> asks you to confirm. If anybody still has no settled result — no status, still on course, or a radio finish whose card hasn&#39;t been read — <strong>Event not finalised</strong> appears instead, listing them with the buttons that settle them. See <a href="./../after-the-event/results#settling-everyone-first">Settling everyone first</a>.</p><p>If Manager is closed while an event is live, the events list offers to resume it next time Manager starts. Decline, and the event is marked <strong>Abandoned</strong>; you can still <strong>Resume event</strong> or <strong>Mark finished</strong> from its app bar later.</p><h3 id="restarting-an-event-you-ve-already-finished" tabindex="-1">Restarting an event you&#39;ve already finished <a class="header-anchor" href="#restarting-an-event-you-ve-already-finished" aria-label="Permalink to &quot;Restarting an event you&#39;ve already finished&quot;">​</a></h3><p>Finishing an event isn&#39;t final. If a competitor walks out of the forest after you&#39;ve closed the event off, open the event and click <strong>Restart event</strong> in the app bar. Manager warns you first, then takes the event live again so you can download the card, fix the result, and finish it a second time.</p><p>This works however long ago the event was — you can restart yesterday&#39;s event tomorrow morning. Reading a card late doesn&#39;t distort anything: the card holds the times of day the competitor actually punched, so their result comes out the same as it would have on the day.</p><p>Two things to know:</p><ul><li>Another event can be live at the same time — see <a href="#two-events-live-at-once">Two events live at once</a> below. The one exception is a replay, which runs on its own.</li><li>Remember to click <strong>Finish event</strong> again when you&#39;re done, so the event goes back to being finished.</li></ul><blockquote><p><strong>Note:</strong> An event that never ran and whose date has passed is the one case Manager won&#39;t start — there&#39;s no <strong>Start event</strong> button for it. Change the date first (<strong>Event details</strong> on the dashboard), then start it.</p></blockquote><h3 id="two-events-live-at-once" tabindex="-1">Two events live at once <a class="header-anchor" href="#two-events-live-at-once" aria-label="Permalink to &quot;Two events live at once&quot;">​</a></h3><p>Two events can be in progress on one Manager at the same time: a morning race whose last runners are still out when the afternoon race starts, or an MTBO and a foot-O on the same day. Start the second event as usual; the first carries on.</p><p>For the setup — how Manager tells the two events&#39; runners apart, and what to check before the first start — see <a href="./two-events-at-once">Running two events at once</a>.</p><ul><li><strong>The radio network is shared.</strong> meshO Prime feeds every live event that uses it. A punch is stored in both events, and counts only in the event whose run it is: the one where its card is entered, or, for a card entered in both or neither, the one its start or check punch belongs to.</li><li><strong>Each download desk reads into the event it has open.</strong> If the card belongs to the other live event, the result says so — <em>This card is entered in Afternoon race (Jane Smith)</em> — with a link to that event&#39;s download page. Read the card again there.</li><li><strong>The radio card download station</strong> (cards read over the radio at the finish) sends each card to the live event where it is entered. If both events have it, the event where that runner has not downloaded yet wins, and after that the most recently started event. A card entered in neither goes to the event that adds competitors for unknown cards, if only one does, and otherwise to the most recently started event.</li><li><strong>Finishing one event leaves the other running</strong>: its backups, its live results export, its liveresultat publishing and its radio feed all carry on.</li><li><strong>Screens follow the most recently started event</strong> unless they are set to one: when the afternoon race starts, the leaderboards and other screens not set to an event move to it. The spectator site, the kiosk and the info displays ask which event to show.</li></ul><p>A replay can&#39;t run while any event is live, and no event can start while a replay runs. A live standby follows every live event, and a take-over takes them all — see <a href="./live-standby">Live standby</a>.</p><h2 id="the-event-header" tabindex="-1">The event header <a class="header-anchor" href="#the-event-header" aria-label="Permalink to &quot;The event header&quot;">​</a></h2><p>The header across the top of the dashboard identifies the event: its <strong>name</strong>, <strong>date</strong>, and a row of attributes — event type (individual / relay / team), competition level, discipline, and whether it&#39;s an individual or mass start — plus an <strong>Eventor</strong> marker if it was imported from Eventor.</p><p>The <strong>Event details</strong> button (top-right of the header) opens the event&#39;s settings: its name and date, starts, radio controls, backups, printing, hire items, live results, extensions and more. See <a href="./../event-setup/create-event#editing-event-details">Editing event details</a>.</p><p><strong>Edit dashboard</strong>, at the right of the header&#39;s details line, lets you rearrange the tiles below — see <a href="#arranging-the-dashboard">Arranging the dashboard</a>.</p><p>If this computer has just <a href="./live-standby">taken the event over</a> from another one, a panel under the header lists what is still to do by hand.</p><h2 id="always-on-tiles" tabindex="-1">Always-on tiles <a class="header-anchor" href="#always-on-tiles" aria-label="Permalink to &quot;Always-on tiles&quot;">​</a></h2><p>Three tiles are always available.</p><h3 id="event-data" tabindex="-1">Event data <a class="header-anchor" href="#event-data" aria-label="Permalink to &quot;Event data&quot;">​</a></h3><p>A count of everything you&#39;ve set up — <strong>controls, courses, classes, competitors</strong> (or <strong>teams</strong> for a relay), and <strong>clubs</strong>. It&#39;s your at-a-glance check that setup is complete: a zero where you expect a number means something hasn&#39;t been imported or created yet. <strong>Click any count</strong> to jump straight to that list, and use <strong>Import</strong> (top-right) to bring in more data. See <a href="./../event-setup/import-event-data">Importing event data</a>.</p><h3 id="competitors" tabindex="-1">Competitors <a class="header-anchor" href="#competitors" aria-label="Permalink to &quot;Competitors&quot;">​</a></h3><p>The headline numbers for the race in progress:</p><ul><li><strong>Total</strong> — everyone entered.</li><li><strong>Not started</strong> — everyone who hasn&#39;t started. Before the first start that&#39;s the whole field; by the end of the day it&#39;s the no-shows, plus anyone already marked <strong>DNS</strong>, <strong>Not competing</strong> or <strong>Cancelled</strong>. <strong>Started</strong> and <strong>Not started</strong> always add up to <strong>Total</strong>, so marking a no-show DNS moves nobody between them.</li><li><strong>Started</strong> — how many have started.</li><li><strong>On course</strong> — how many Manager believes are <strong>still out on the course</strong>, including anyone who has checked in and not come back. This is your safety number.</li><li><strong>Pending</strong> — runners who have crossed a <strong>radio finish</strong> but whose <strong>card hasn&#39;t been downloaded yet</strong>, so their result is still <em>preliminary</em>. (Only shown once radio punches are arriving.)</li><li><strong>Finished</strong> — competitors who are back with a status: OK, MP, DNF, DSQ, overtime or not competing. Pending runners are counted here too, since the radio saw them finish; <strong>Pending</strong> tells you how many of those still need their card read.</li></ul><p>A live mini-chart below the numbers tracks the On course count over time, so you can see the field flow out and back.</p><p><strong>Not started</strong>, <strong>On course</strong> and <strong>Pending</strong> are clickable — they&#39;re drawn as coloured, raised buttons whenever they have something to show. Clicking opens the list behind each. At zero they look like the plain counts either side of them, so a coloured button always means there&#39;s a list to open.</p><p>The counts stay on <strong>one line</strong> whatever width you drag the tile to — they shrink, and their labels drop, rather than wrapping. <strong>Not started</strong> is the one that gives way: it isn&#39;t shown once the tile is too narrow to fit its label in full, since it&#39;s the only number you can work out from the others (Total minus Started). Widen the tile to bring it back. (It&#39;s measured against the label as your language actually writes it, so the width it needs differs between languages.)</p><p>Click <strong>Not started</strong> for the list of everyone yet to go out: name, card, class, start time and status. The <strong>Status</strong> column is what separates the two kinds of name on it — a blank status is somebody nobody has accounted for yet, while <strong>DNS</strong>, <strong>Not competing</strong> or <strong>Cancelled</strong> is an absence you (or a <a href="./safety-check#course-closure-settling-the-list-at-a-set-time">course closure</a>) have already dealt with. Click a name to open their record.</p><blockquote><p><strong>Safety — is everyone back?</strong> <strong>On course</strong> is the number that matters at the end of the day. While it&#39;s above zero, click it to open the <strong>On course</strong> list and work through who&#39;s still out, who has finished but not downloaded, and who never started. The full procedure — including reading start/finish station memory and clearing no-shows — is on its own page: <strong><a href="./safety-check">Safety check: accounting for everyone</a></strong>. Click <strong>Pending</strong> to see the preliminary-result runners due at the download desk. For every <em>other</em> place the same picture surfaces, see <a href="./who-is-still-on-course">Seeing who is still on course</a>.</p></blockquote><h2 id="the-other-tiles" tabindex="-1">The other tiles <a class="header-anchor" href="#the-other-tiles" aria-label="Permalink to &quot;The other tiles&quot;">​</a></h2><p>The rest of the dashboard depends on which features the event uses. A tile that only does something while the event is running — a card download, a radio punch — stays on the dashboard in setup and after the finish, but goes quiet and says so, rather than disappearing.</p><table tabindex="0"><thead><tr><th>Tile</th><th>What it shows</th><th>When it&#39;s there</th></tr></thead><tbody><tr><td><strong>Quick competitor actions</strong> (<strong>Quick actions</strong> when the tile is narrow)</td><td>Search and open a competitor; change their card number or class; print their splits; allow a punching start; <strong>+</strong> to add a competitor</td><td>Always</td></tr><tr><td><strong>Download card</strong></td><td>Reader connection and live card downloads</td><td>Always, except during a replay; quiet unless the event is running</td></tr><tr><td><strong>Radio controls</strong></td><td>meshO Prime&#39;s connection, punch activity over the last 30 minutes, and each meshO Control&#39;s health and alerts</td><td>The event uses meshO Prime for radio punches</td></tr><tr><td><strong>Radio punch forwarding</strong></td><td>Outbound forwarding status — <strong>Active</strong>/<strong>Disabled</strong>, with <strong>Sent</strong> and <strong>Queued</strong> counts</td><td>The event uses meshO Prime and has <strong>Forward radio punches</strong> on</td></tr><tr><td><strong>SIRAP punch listening</strong></td><td>Inbound SIRAP punch source — <strong>Listening</strong>/<strong>Stopped</strong>, the port, and a <strong>Received</strong> count that restarts when an event starts accepting punches</td><td>The event has <strong>Accept SIRAP punches</strong> on</td></tr><tr><td><strong>Spectators</strong></td><td>How many people are <strong>watching now</strong> on the live screens, with the last 60 minutes as a sparkline</td><td>Always; quiet unless the event is running</td></tr><tr><td><strong>Liveresultat</strong></td><td>Whether the competition exists, whether it is listed, and whether uploads are getting through</td><td>The event publishes to liveresultat</td></tr><tr><td><strong>Recent downloads</strong></td><td>The last cards read, newest first — the <strong>time</strong>, each competitor&#39;s <strong>name</strong> and <strong>status</strong></td><td>You add it yourself (see below)</td></tr><tr><td><strong>Pending downloads</strong></td><td>Who the radio saw finish and hasn&#39;t downloaded — the <strong>finish time</strong>, their <strong>name</strong>, and how long they&#39;ve been <strong>waiting</strong></td><td>You add it yourself (see below)</td></tr><tr><td><strong>Extension tiles</strong></td><td>Whatever an installed extension contributes</td><td>An extension that provides a tile is enabled for the event</td></tr></tbody></table><p>A few of these have their own pages:</p><ul><li><strong>Quick competitor actions</strong> is the fastest way to fix a single competitor&#39;s card or class without leaving the dashboard — for deeper edits, open them in the <a href="./../event-setup/competitors-clubs-teams">Competitors list</a>. The printer button beside the search prints the selected competitor&#39;s splits, once their card has been read — see <a href="./splits-printing#printing-by-hand-and-reprinting">Printing splits</a>. When you are done with one runner, click the <strong>×</strong> in the search to clear them and type the next name. Press <strong>Ctrl+F</strong> (<strong>⌘F</strong> on a Mac) anywhere on the dashboard to put the cursor in the search, ready to type a name. The eye button beside the search opens the competitor&#39;s full record. With a SportIdent reader connected, click into the <strong>Card number</strong> box and insert a card to fill in its number, rather than downloading it. At an event where allocated start times win, an <strong>Allow punching start</strong> button also appears for a runner left on the event&#39;s setting, so a runner who was late to the start through no fault of their own is timed from their start punch — see <a href="./../event-setup/start-times#punched-starts">Punched starts</a>.</li><li><strong>Download card</strong> is a compact version of the full <a href="./card-download">Card downloads</a> page. A reader connected here is the same reader the Card downloads page and the SportIdent station page use, and downloads register from anywhere, so the tile updates even when you&#39;re elsewhere. When cards are waiting for an owner, the tile says how many, with <strong>Show</strong> to list them.</li><li><strong>Radio controls</strong> is your radio-network health panel. While meshO Prime isn&#39;t connected it shows Prime&#39;s state — <strong>Searching</strong>, <strong>Lost</strong>, <strong>Offline</strong> or <strong>Not configured</strong> — with a <strong>Diagnostics</strong> button. Once Prime is <strong>Online</strong> it shows a bar chart of punches over the last 30 minutes, a coloured dot per meshO Control (green when heard in the last two minutes, orange after two, red after five, grey if never heard), a count of low batteries, and the alerts for each unit: battery low or critical, connection lost, weak signal, no location. The arrow at the top right opens the <a href="./connecting-prime-and-radios#watching-the-radio-network-during-the-event">Radios</a> page. See also <a href="./radio-punches">Radio punches</a>.</li><li><strong>Spectators</strong> is a summary of the <strong>Spectators</strong> page under <strong>Event live</strong> — see <a href="./../screens/spectator-site-and-kiosk#spectator-analytics">Spectator analytics</a>.</li><li><strong>Liveresultat</strong> is covered in <a href="./publishing-live-results#checking-it-is-working">Publishing live results online</a>.</li><li><strong>Extension tiles</strong> come from add-ons you&#39;ve installed — see <a href="./../advanced/installing-extensions">Installing extensions</a>.</li></ul><h3 id="recent-downloads-—-a-tile-you-switch-on" tabindex="-1">Recent downloads — a tile you switch on <a class="header-anchor" href="#recent-downloads-—-a-tile-you-switch-on" aria-label="Permalink to &quot;Recent downloads — a tile you switch on&quot;">​</a></h3><p><strong>Recent downloads</strong> starts off the dashboard, because the <a href="./card-download">Card downloads</a> page already lists every download in full. Add it when you want the last few in the corner of your eye: click <strong>Edit dashboard</strong> in the event header, choose <strong>Add tile → Recent downloads</strong>, drag and resize it where you want it, then click <strong>Done</strong>. It stays there for next time.</p><p>The tile shows one card per download, newest at the top: the <strong>time</strong> it was read, the competitor&#39;s <strong>name</strong> and their <strong>status</strong> chip. <strong>Click one to open that competitor&#39;s record</strong>, which is where you change a class or fix a mis-punch — the same dialog you get from the Competitors list.</p><p>It shows exactly as many as fit in the tile and no more — it never scrolls, and never cuts a name in half. Make the tile taller to see further back. Narrow it and the time drops off, so names keep their room; widen it and the time comes back.</p><p>A card that hasn&#39;t been matched to anybody yet shows its <strong>card number</strong> and an <strong>Unassigned</strong> chip instead. <strong>Click that one and you land on the <a href="./card-download">Card downloads</a> page with the card already open</strong>, ready to give it an owner — every card in the tile goes somewhere.</p><p>Like the <strong>Download card</strong> tile, it stays on the dashboard but goes quiet when the event isn&#39;t running — cards can only arrive while the event is live.</p><h3 id="pending-downloads-—-the-tile-the-download-tent-watches" tabindex="-1">Pending downloads — the tile the download tent watches <a class="header-anchor" href="#pending-downloads-—-the-tile-the-download-tent-watches" aria-label="Permalink to &quot;Pending downloads — the tile the download tent watches&quot;">​</a></h3><p><strong>Pending downloads</strong> is the mirror image: not the cards that have come in, but the ones that haven&#39;t. It lists the runners a <strong>radio finish</strong> saw come back whose card has never been read — the people who walk off towards the car park with it still in their hand.</p><p>It starts off the dashboard too, because the <a href="./who-is-still-on-course#the-pending-downloads-info-screen">Pending downloads info screen</a> is where the tent usually watches this list. Add it the same way: <strong>Edit dashboard → Add tile → Pending downloads</strong>.</p><p>Longest wait at the top. Each row carries the <strong>time</strong> the radio put them across the line, their <strong>name</strong>, and how long they have been <strong>waiting</strong> since — counting up once a second, from the event clock. <strong>Click a row to open that competitor&#39;s record</strong>, which is where somebody who never came back is marked DNF, or the wrong card number that is why nothing was ever read against them gets fixed.</p><p>Runners still <strong>on course</strong> are deliberately <em>not</em> on it, exactly as on the info screen: they are a different problem — somebody who may still be running — and on the same list they would bury the two or three names the tent is actually chasing.</p><p><strong><code>--:--</code> means Manager cannot say, not zero.</strong> A runner whose finish time it never recorded, or an event with no clock running, shows the sentinel rather than a number. Their name is still on the list; that is the part that matters.</p><p>Like <strong>Recent downloads</strong>, it sizes itself to the tile — as many whole rows as fit, never scrolling and never half a name — and it stays on the dashboard but goes quiet when the event isn&#39;t running.</p><h2 id="arranging-the-dashboard" tabindex="-1">Arranging the dashboard <a class="header-anchor" href="#arranging-the-dashboard" aria-label="Permalink to &quot;Arranging the dashboard&quot;">​</a></h2><p>Click <strong>Edit dashboard</strong> in the event header to rearrange the tiles. While editing you can:</p><ul><li><strong>drag</strong> a tile to move it, and drag its edges to make it wider, narrower, taller or shorter;</li><li><strong>Hide</strong> a tile you don&#39;t use;</li><li><strong>Add tile</strong> to bring back a hidden one, or add one that starts hidden, such as <strong>Recent downloads</strong> or <strong>Pending downloads</strong>;</li><li><strong>Reset layout</strong> to go back to the default arrangement.</li></ul><p>Click <strong>Done</strong> when you&#39;re finished. The arrangement is kept in this browser, and it&#39;s the same for every event you open on this computer; another computer has its own.</p><h2 id="reading-the-colours" tabindex="-1">Reading the colours <a class="header-anchor" href="#reading-the-colours" aria-label="Permalink to &quot;Reading the colours&quot;">​</a></h2><p>Colour is used consistently across the dashboard so problems catch your eye:</p><ul><li><strong>Green</strong> — healthy or live: a live event, a connected reader (<strong>Listening</strong>), forwarding that&#39;s <strong>Active</strong>, controls reporting in normally.</li><li><strong>Orange / yellow</strong> — attention, not yet a failure: punches <strong>Queued</strong> for forwarding, a control on <strong>low battery</strong> (25% or less), weak signal or quiet for two minutes, an interrupted event.</li><li><strong>Red / grey</strong> — stopped or finished: an <strong>abandoned</strong> (red) or <strong>complete</strong> (grey) event, a critical battery (5% or less), a control not heard for five minutes, or (grey) never heard at all.</li></ul><p>When the <strong>Radio controls</strong> tile flags low batteries or a silent control, treat it as an early warning and check that unit before it costs you punches.</p><h2 id="what-isn-t-on-the-dashboard" tabindex="-1">What isn&#39;t on the dashboard <a class="header-anchor" href="#what-isn-t-on-the-dashboard" aria-label="Permalink to &quot;What isn&#39;t on the dashboard&quot;">​</a></h2><p>A couple of common jobs live elsewhere, by design:</p><ul><li><strong>Marking competitors DNS in bulk</strong> is done from <strong>Competitors → Actions → Set competitors DNS…</strong>, not here. See <a href="./safety-check">Safety check</a>.</li><li><strong>Re-checking a download, overriding a status, or editing punches</strong> is done from the <a href="./card-download">Card downloads</a> page or the competitor&#39;s record — see <a href="./resolving-issues">Resolving issues on the day</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./safety-check">Safety check: accounting for everyone</a> — working the On course list</li><li><a href="./who-is-still-on-course">Seeing who is still on course</a> — every place the on-course picture surfaces</li><li><a href="./card-download">Downloading cards</a> — the Card downloads page in full</li><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a> — the radio network behind the Radio controls tile</li><li><a href="./radio-punches">Radio punches</a> — punches arriving live from the field</li><li><a href="./resolving-issues">Resolving issues on the day</a> — fixing competitors and results</li><li><a href="./../event-setup/create-event#editing-event-details">Creating an event</a> — the event lifecycle and Event details</li><li><a href="./live-standby">Live standby</a> — a second computer ready to take over</li><li><a href="./two-events-at-once">Running two events at once</a> — setting up a second live event on the same day</li></ul>',70)])])}const p=t(a,[["render",r]]);export{u as __pageData,p as default};
